WITH valid AS (SELECT id, order_id, method, amount, paid_at, status, CONCAT(method, ' - ', status) AS method_status, MONTH(paid_at) AS paid_at_month FROM payments WHERE paid_at > TIMESTAMP '2023-10-29 06:00:00') SELECT id, order_id, method, paid_at FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, order_id ORDER BY paid_at_month DESC, id) AS dedup_rank FROM valid) t WHERE dedup_rank = 1;
